async def _locate(self, s:str) -> "list[Element]":                               # BrowserGroup
    ans = []; res = [self._addE(d) for d in await self.browser._sendExt({"cmd": "locate", "selector": self.selector, "s": s})] # BrowserGroup
    for e in res:                                                                # BrowserGroup
        if s in e.extras["text"]: ans.append(e)                                  # BrowserGroup
        elif s in await e.value("textContent"): ans.append(e)                    # BrowserGroup
    return ans                                                                   # BrowserGroup
